package za.ac.univen.clone;
import java.util.*;
import java.util.regex.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

final class PortalParser {
 record Contract(String label,String path,List<String> headers){}
 static final Map<String,Contract> CONTRACTS=Map.of(
  "admission",new Contract("Academic Admission Status","w63pkg.w63_lst_frm",List.of("Year","Qualification","Qualification","Faculty","Status","Academic Choice","Contract Code","Quote Number","Quote Total")),
  "results",new Contract("Assessment Status","w68pkg.w68_lst_frma",List.of("Subject Code","Subject Name","Year","Block")),
  "contacts",new Contract("Personal Contact Detail","w59pkg.w59_lst_frm",List.of("Communication Type","Detail","Internet Service Provider")),
  "documents",new Contract("Certificates seen","w34pkg.w34_lst_frm",List.of("","Certificate","","Processed","Expiry Date","Remarks","Load/View","Uploaded via the web")),
  "residenceApplications",new Contract("Submit Residence Application","w43pkg.w43startup",List.of("Academic Year","Residence Period","Building","Admission Status")),
  "progress",new Contract("Progress Report","w62pkg.w62_lst_frm",List.of()),
  "residenceProof",new Contract("Residence Proof of Registration","web.ws24pkg.ws24pkg_res_por",List.of()));
 static String clean(String html){return Jsoup.parse(html).text().replace('\u00a0',' ').trim();}
 static String visible(Element element){var copy=element.clone();copy.select("script,style,input[type=hidden],[hidden],[aria-hidden=true]").remove();for(Element input:copy.select("input:not([type=submit]):not([type=button]):not([type=image]),textarea,select"))input.replaceWith(new TextNode(input.val()));return copy.text().replace('\u00a0',' ').trim();}
 static Document checked(String html,String student){var doc=Jsoup.parse(html);String body=visible(doc.body());if(Pattern.compile("Checksum validation failed|Access Denied|Illegal Login|Invalid Login|Maximum Unsuccessful Login",Pattern.CASE_INSENSITIVE).matcher(body).find()||!doc.select("input[type=password]").isEmpty())throw ApiProblem.expired();String number=Data.match("Student Number:\\s*(\\d+)",body);if(!number.isEmpty()&&!number.equals(student))throw new ApiProblem(403,"ACCESS_DENIED","The portal returned a different student account.");return doc;}
 static void verifyProfile(String html,String student){checked(html,student);String number=Data.match("<th>Student(?:&nbsp;|\\s+)Nbr</th>\\s*<td>([^<]+)</td>",html);if(number.isEmpty())throw ApiProblem.changed();if(!number.trim().equals(student))throw new ApiProblem(403,"ACCESS_DENIED","The portal returned a different student account.");}
 static List<String> cells(Element row){var result=new ArrayList<String>();for(Element cell:row.children()){if(!Set.of("td","th").contains(cell.tagName()))continue;int span=1;try{if(cell.hasAttr("colspan"))span=Integer.parseInt(cell.attr("colspan"));if(cell.hasAttr("rowspan")&&!cell.attr("rowspan").equals("1"))throw ApiProblem.changed();}catch(NumberFormatException e){throw ApiProblem.changed();}if(span<1||span>20)throw ApiProblem.changed();for(int i=0;i<span;i++)result.add(visible(cell));}return result;}
 static Map<String,Object> table(Element head,List<String> headers,String heading,String caption){Element table=head.closest("table");if(table==null)throw ApiProblem.changed();var rows=new ArrayList<Map<String,Object>>();for(Element row:table.select("tr.rldata")){if(row.closest("table")!=table)continue;var values=cells(row);if(values.size()!=headers.size())throw ApiProblem.changed();rows.add(Data.map("rowIndex",rows.size()+1,"cells",values));}return Data.map("heading",heading,"caption",caption,"headers",headers,"rows",rows);}
 static Map<String,Object> read(String html,String section,String student){var doc=checked(html,student);var contract=CONTRACTS.get(section);var heads=doc.select("tr.rlheader,tr.tbl_header").stream().filter(row->cells(row).equals(contract.headers())).toList();if(heads.size()!=1)throw ApiProblem.changed();var table=table(heads.getFirst(),contract.headers(),contract.label(),null);var years=new HashSet<String>();int index=contract.headers().indexOf("Year");if(index<0)index=contract.headers().indexOf("Academic Year");if(index>=0)for(var row:Data.list(table.get("rows"))){String year=Data.str(((List<?>)row.get("cells")).get(index));if(year.matches("\\d{4}"))years.add(year);}return result(List.of(table),List.of(),List.of(),years.size()==1?years.iterator().next():null,Data.list(table.get("rows")).isEmpty());}
 static Map<String,Object> detail(String html,String student,String code){var doc=checked(html,student);if(!visible(doc.body()).contains("Subject "+code+" -"))throw ApiProblem.changed();var expected=List.of("Group Type and Name","Group Type and Name","AN","Status","Mark","Result","Mark Type","CB","CP","SM","W");var heads=doc.select("tr.rlheader").stream().filter(row->cells(row).equals(expected)).toList();if(heads.size()!=1)throw ApiProblem.changed();var headers=new ArrayList<>(expected);headers.set(0,"Group Type");headers.set(1,"Group Name");return table(heads.getFirst(),headers,code,"Assessment Status");}
 static Map<String,Object> progress(String html,String student){var doc=checked(html,student);var tables=new ArrayList<Map<String,Object>>();var years=new HashSet<String>();String qualification=null,year=null;for(Element table:doc.select("table")){if(table.parents().stream().anyMatch(p->p.tagName().equals("table")))continue;String found=Data.match("^Year:\\s*(\\d{4})",visible(table));if(!found.isEmpty()){year=found;years.add(year);qualification=visible(table);continue;}Map<String,Object> current=null;int index=0;for(Element row:table.select("tr")){if(row.closest("table")!=table)continue;index++;var values=cells(row);if(!values.isEmpty()&&values.getFirst().startsWith("Subject:")){if(year==null)throw ApiProblem.changed();current=Data.map("heading",values.getFirst(),"caption",qualification,"headers",List.of("","",""),"rows",new ArrayList<Map<String,Object>>());tables.add(current);}else if(current!=null&&values.stream().anyMatch(s->!s.isBlank())){if(values.size()>3)throw ApiProblem.changed();while(values.size()<3)values.add("");Data.list(current.get("rows")).add(Data.map("rowIndex",index,"cells",values));}}}if(tables.isEmpty())throw ApiProblem.changed();return result(tables,List.of(),List.of(),years.size()==1?years.iterator().next():null,false);}
 static Map<String,Object> result(List<Map<String,Object>> tables,List<Map<String,Object>> fields,List<String> warnings,String year,boolean empty){return Data.map("status",warnings.isEmpty()?(empty?"empty":"ok"):"partial","data",Data.map("tables",new ArrayList<>(tables),"fields",fields,"messages",List.of()),"warnings",new ArrayList<>(warnings),"academicYear",year,"retrievedAt",java.time.Instant.now().toString(),"error",null);}
 record Menu(String label,String url,String parent){}
 static List<Menu> menu(String html){String script=Jsoup.parse(html).select("script").stream().map(Element::data).reduce("",(a,b)->a+"\n"+b);try{List<?> labels=Data.JSON.readValue("["+Data.match("var\\s+i_text\\s*=\\s*new Array\\(([^;]*)\\);",script)+"]",List.class);List<?> urls=Data.JSON.readValue("["+Data.match("var\\s+i_url\\s*=\\s*new Array\\(([^;]*)\\);",script)+"]",List.class);List<?> levels=Data.JSON.readValue("["+Data.match("var\\s+i_level\\s*=\\s*new Array\\(([^;]*)\\);",script)+"]",List.class);if(labels.isEmpty()||labels.size()!=urls.size()||labels.size()!=levels.size())throw ApiProblem.changed();String[] parents=new String[3];var result=new ArrayList<Menu>();for(int i=0;i<labels.size();i++){if(!(labels.get(i) instanceof String)||!(urls.get(i) instanceof String)||!(levels.get(i) instanceof Integer))throw ApiProblem.changed();int level=(Integer)levels.get(i);if(level<1||level>3)throw ApiProblem.changed();String label=labels.get(i).toString();result.add(new Menu(label,urls.get(i).toString(),level>1?parents[level-2]:null));parents[level-1]=label;}return result;}catch(ApiProblem e){throw e;}catch(Exception e){throw ApiProblem.changed();}}
 static String field(String html,String label){return clean(Data.match("<th>"+label+"</th>\\s*<td[^>]*>([\\s\\S]*?)</td>",html));}
 static String pair(String html,String label){var matcher=Pattern.compile("<th>"+label+"</th>\\s*<td[^>]*>([^<]*)</td>\\s*<td[^>]*>([\\s\\S]*?)</td>",Pattern.CASE_INSENSITIVE).matcher(html);return matcher.find()?clean(matcher.group(1))+" - "+clean(matcher.group(2)):"";}
 static String lastField(String html,String label){return clean(Data.match("<th>"+label+"</th>\\s*<td[^>]*>[^<]*</td>\\s*<td[^>]*>([\\s\\S]*?)</td>",html));}
 static Map<String,Object> profile(String html,String studentNumber){verifyProfile(html,studentNumber);var qualifications=new ArrayList<Map<String,Object>>();var pattern=Pattern.compile("<th>Qualification</th>\\s*<td[^>]*>([^<]+)</td>\\s*<td[^>]*>\\s*(?:<span>)?([^<]+)",Pattern.CASE_INSENSITIVE);var matcher=pattern.matcher(html);var starts=new ArrayList<Integer>();var codes=new ArrayList<String>();var names=new ArrayList<String>();while(matcher.find()){starts.add(matcher.start());codes.add(clean(matcher.group(1)));names.add(clean(matcher.group(2)));}
  for(int i=0;i<starts.size();i++){String chunk=html.substring(starts.get(i),i+1<starts.size()?starts.get(i+1):html.length());String yearText=lastField(chunk,"Registration(?:&nbsp;|\\s+)Year");int year=yearText.matches("\\d{4}")?Integer.parseInt(yearText):0;var modules=new ArrayList<Map<String,Object>>();var rows=Pattern.compile("<tr class=[\"']?rldata[\"']?[^>]*>([\\s\\S]*?)</tr>",Pattern.CASE_INSENSITIVE).matcher(chunk);while(rows.find()){var cells=new ArrayList<String>();var tds=Pattern.compile("<td[^>]*>([\\s\\S]*?)</td>",Pattern.CASE_INSENSITIVE).matcher(rows.group(1));while(tds.find())cells.add(clean(tds.group(1)));if(cells.size()<8)continue;String code=cells.getFirst();var module=Data.map("code",code,"name",cells.get(1),"semester",code.matches(".*(?:51|11|21|31).* ")?"Semester 1":"Semester 2","year",year,"credits",code.contains("5241")?32:16,"classGroup",at(cells,4),"attendance",at(cells,7),"examGranted",Set.of("Yes","Y").contains(at(cells,11))?"Yes":Set.of("No","N").contains(at(cells,11))?"No":"Pending","examMonth",at(cells,12),"withheldReason",at(cells,17));Double progress=mark(at(cells,14)),finalMark=mark(at(cells,15));module.put("progressMark",progress);module.put("finalMark",finalMark);module.put("status",finalMark==null?"Enrolled":finalMark>=75?"Distinction":finalMark>=50?"Pass":"Fail");modules.add(module);}
   qualifications.add(Data.map("qualificationCode",codes.get(i),"qualificationName",names.get(i),"registrationYear",year,"academicBlock",pair(chunk,"Academic(?:&nbsp;|\\s+)Block"),"faculty",pair(chunk,"Faculty"),"department",pair(chunk,"Department"),"offeringType",pair(chunk,"Offering(?:&nbsp;|\\s+)Type"),"periodOfStudy",field(chunk,"Period(?:&nbsp;|\\s+)of(?:&nbsp;|\\s+)Study"),"registrationDates",lastField(chunk,"Registration(?:&nbsp;|\\s+)Dates"),"hasBursary",field(chunk,"Has Bursary").equalsIgnoreCase("Y"),"modules",modules));
  }
  qualifications.sort((a,b)->Integer.compare((int)b.get("registrationYear"),(int)a.get("registrationYear")));int currentYear=java.time.Year.now().getValue();var current=qualifications.stream().filter(q->q.get("registrationYear").equals(currentYear)).findFirst();var active=current.orElse(qualifications.isEmpty()?Data.map():qualifications.getFirst());String fullName=clean(Data.match("<th[^>]*colspan=[\"']?2[\"']?[^>]*>([^<]+)</th>",html));String[] nameParts=fullName.split("[ ,]+");String preferred=nameParts.length>1?nameParts[1]:fullName;if(!preferred.isEmpty())preferred=preferred.substring(0,1).toUpperCase()+preferred.substring(1).toLowerCase();
  var doc=Jsoup.parse(html);var fees=new ArrayList<Map<String,Object>>();for(Element row:doc.select("#feeDiv tr.rldata")){var c=cells(row);if(c.size()<6)continue;fees.add(Data.map("id","stmt-"+fees.size(),"date",c.get(0),"reference",c.get(1),"description",c.get(2),"debit",Data.number(c.get(3)),"credit",Data.number(c.get(4)),"balance",Data.number(c.get(5)),"type","Tuition"));}
  var bursaries=new ArrayList<Map<String,Object>>();for(Element row:doc.select("#bursDiv tr.rldata")){var c=cells(row);if(c.size()<6)continue;bursaries.add(Data.map("year",(int)Data.number(c.get(0)),"bursaryCode",c.get(1),"description",c.get(2),"isNsfas",(c.get(1)+c.get(2)).toUpperCase().contains("NSFAS"),"awarded",Data.number(c.get(3)),"allocated",Data.number(c.get(4)),"unallocated",Data.number(c.get(5))));}
  var age=Data.map();String[] ageKeys={"d160","d90","d60","d30","current","credit","future","unallocated","balance"};Element ageRow=doc.selectFirst("#ageAnalysisDiv tr.rldata");var ageValues=ageRow==null?List.<String>of():cells(ageRow);for(int i=0;i<ageKeys.length;i++)age.put(ageKeys[i],ageValues.size()>i?Data.number(ageValues.get(i)):0);
  var balance=Pattern.compile("<td>Fee</td>\\s*<td[^>]*>([^<]+)</td>\\s*<td[^>]*>([^<]+)</td>\\s*<td[^>]*>([^<]+)</td>\\s*<td>([^<]+)</td>",Pattern.CASE_INSENSITIVE).matcher(html);boolean hasBalance=balance.find();double owed=Data.number(field(html,"You owe the institution:?\\s*"));if(hasBalance)owed=Data.number(balance.group(3));
  String registration=current.isPresent()?"Currently Registered":qualifications.isEmpty()?"Not Registered":"Previously Registered";
  var student=Data.map("studentNumber",studentNumber,"fullName",fullName,"preferredName",preferred.isEmpty()?"Student":preferred,"gender",field(html,"Gender"),"dateOfBirth",field(html,"Birthdate"),"idNumber",field(html,"ID(?:&nbsp;|\\s+)Nbr"),"maritalStatus",field(html,"Marital(?:&nbsp;|\\s+)Status"),"homeLanguage",field(html,"Home(?:&nbsp;|\\s+)Lang(?:uage)?"),"citizenship",field(html,"Citizenship"),"institutionalEmail",Data.match("mailto:([^\"']+)",html),"cellphoneNumber",contact(html,"Cellphone"),"postalAddress",contact(html,"Postal Address"),"studyAddress",contact(html,"Study Address"),"qualification",active.getOrDefault("qualificationName",""),"qualificationCode",active.getOrDefault("qualificationCode",""),"academicYear",active.getOrDefault("registrationYear",currentYear),"faculty",active.getOrDefault("faculty",""),"department",active.getOrDefault("department",""),"periodOfStudy",active.getOrDefault("periodOfStudy",""),"academicBlock",active.getOrDefault("academicBlock",""),"offeringType",active.getOrDefault("offeringType",""),"registrationDates",active.getOrDefault("registrationDates",""),"hasBursary",active.getOrDefault("hasBursary",false),"admissionStatus",registration,"registrationStatus",registration,"isCurrentlyRegistered",current.isPresent(),"currentRegistrationYear",current.isPresent()?currentYear:null,"latestRegistrationYear",active.get("registrationYear"),"nsfasFunded",bursaries.stream().anyMatch(b->Boolean.TRUE.equals(b.get("isNsfas"))),"currentAccountBalance",owed,"totalDebit",hasBalance?Data.number(balance.group(1)):owed,"totalCredit",hasBalance?Data.number(balance.group(2)):0,"dateOfBalance",hasBalance?clean(balance.group(4)):"","profileImageUrl","","historicalQualifications",qualifications);
  return Data.map("student",student,"modules",active.getOrDefault("modules",List.of()),"statements",fees,"ageAnalysis",age,"bursaries",bursaries,"historicalQualifications",qualifications);
 }
 static String at(List<String> values,int index){return values.size()>index?values.get(index):"";}
 static Double mark(String value){try{return Double.valueOf(value);}catch(Exception e){return null;}}
 static String contact(String html,String label){return clean(Data.match(label+"</div>\\s*</div>\\s*<div>([^<]+)</div>",html));}
}
